func TestMigrationRegistry_ConcurrentAccess(t *testing.T) {
	noopMigrator := func(ctx context.Context, orgId int64, opts MigrateOptions, stream resourcepb.BulkStore_BulkProcessClient) error {
		return nil
	}

	t.Run("concurrent register and get operations", func(t *testing.T) {
		r := NewMigrationRegistry()
		var wg sync.WaitGroup
		numGoroutines := 100

		// Pre-register some definitions to avoid panic from duplicates
		for i := 0; i < numGoroutines; i++ {
			def := testMigrationDefinition("def-" + string(rune('a'+i%26)) + string(rune('0'+i/26)))
			gr := testGroupResource("group", "resource-"+string(rune('a'+i%26))+string(rune('0'+i/26)))
			def.Migrators[gr] = noopMigrator
			r.Register(def)
		}

		// Concurrent reads
		wg.Add(numGoroutines * 3)

		// Goroutines calling Get
		for i := 0; i < numGoroutines; i++ {
			go func(i int) {
				defer wg.Done()
				id := "def-" + string(rune('a'+i%26)) + string(rune('0'+i/26))
				_, _ = r.Get(id)
			}(i)
		}

		// Goroutines calling All
		for i := 0; i < numGoroutines; i++ {
			go func() {
				defer wg.Done()
				_ = r.All()
			}()
		}

		// Goroutines calling HasResource
		for i := 0; i < numGoroutines; i++ {
			go func(i int) {
				defer wg.Done()
				gr := testGroupResource("group", "resource-"+string(rune('a'+i%26))+string(rune('0'+i/26)))
				_ = r.HasResource(gr)
			}(i)
		}

		wg.Wait()
	})

	t.Run("concurrent All calls return consistent data", func(t *testing.T) {
		r := NewMigrationRegistry()

		// Register some definitions
		for i := 0; i < 10; i++ {
			r.Register(testMigrationDefinition("def-" + string(rune('a'+i))))
		}

		var wg sync.WaitGroup
		results := make([][]MigrationDefinition, 50)

		for i := 0; i < 50; i++ {
			wg.Add(1)
			go func(idx int) {
				defer wg.Done()
				results[idx] = r.All()
			}(i)
		}

		wg.Wait()

		// All results should be identical
		expected := results[0]
		for i, result := range results {
			require.Len(t, result, len(expected), "result %d has different length", i)
			for j := range result {
				require.Equal(t, expected[j].ID, result[j].ID, "result %d has different ID at index %d", i, j)
			}
		}
	})

	t.Run("concurrent GetMigratorFunc calls", func(t *testing.T) {
		r := NewMigrationRegistry()

		gr := testGroupResource("test.group", "widgets")
		def := testMigrationDefinition("test")
		def.Migrators[gr] = noopMigrator
		r.Register(def)

		var wg sync.WaitGroup
		for i := 0; i < 100; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()
				fn := r.GetMigratorFunc(gr)
				require.NotNil(t, fn)
			}()
		}

		wg.Wait()
	})
}

package migrations

import (
	"context"
	"fmt"

	"github.com/grafana/grafana/pkg/infra/db"
	"github.com/grafana/grafana/pkg/infra/kvstore"
	"github.com/grafana/grafana/pkg/infra/log"
	"github.com/grafana/grafana/pkg/infra/metrics"
	sqlstoremigrator "github.com/grafana/grafana/pkg/services/sqlstore/migrator"
	"github.com/grafana/grafana/pkg/setting"
	"github.com/grafana/grafana/pkg/storage/legacysql"
	"github.com/grafana/grafana/pkg/storage/unified/migrations/contract"
	"github.com/grafana/grafana/pkg/storage/unified/resource"
	"github.com/prometheus/client_golang/prometheus"
	"go.opentelemetry.io/otel"
)

var tracer = otel.Tracer("github.com/grafana/grafana/pkg/storage/unified/migrations")
var logger = log.New("storage.unified.migrations")

type UnifiedStorageMigrationServiceImpl struct {
	migrator     UnifiedMigrator
	tableLocker  MigrationTableLocker
	tableRenamer MigrationTableRenamer
	cfg          *setting.Cfg
	sqlStore     db.DB
	kv           kvstore.KVStore
	client       resource.ResourceClient
	registry     *MigrationRegistry
	gcGate       *resource.GCGate
}

var _ contract.UnifiedStorageMigrationService = (*UnifiedStorageMigrationServiceImpl)(nil)

// ProvideUnifiedStorageMigrationService is a Wire provider that creates the migration service.
func ProvideUnifiedStorageMigrationService(
	migrator UnifiedMigrator,
	sql legacysql.LegacyDatabaseProvider,
	cfg *setting.Cfg,
	sqlStore db.DB,
	kv kvstore.KVStore,
	client resource.ResourceClient,
	registry *MigrationRegistry,
	gcGate *resource.GCGate,
) contract.UnifiedStorageMigrationService {
	lockingEnabled := cfg.Raw.Section("unified_storage").Key("migration_locking").MustBool(true)
	if !lockingEnabled {
		logger.Warn("unified_storage.migration_locking is disabled; source tables are NOT locked " +
			"during migration and legacy tables are NOT renamed. Concurrent writes may be missed " +
			"(data drift). Only safe when no other writers exist during migration (single instance, " +
			"no HA, no rolling upgrades).")
	}
	return &UnifiedStorageMigrationServiceImpl{
		migrator:     migrator,
		tableLocker:  newTableLocker(sqlStore, sql, lockingEnabled),
		tableRenamer: newTableRenamer(string(sqlStore.GetDBType()), logger, cfg.RenameWaitDeadline),
		cfg:          cfg,
		sqlStore:     sqlStore,
		kv:           kv,
		client:       client,
		registry:     registry,
		gcGate:       gcGate,
	}
}

func (p *UnifiedStorageMigrationServiceImpl) Run(ctx context.Context) error {
	// Start GC after migration for chunked history + backfill transactions.
	defer p.gcGate.Release()

	if !p.cfg.ShouldRunMigrations() {
		metrics.MUnifiedStorageMigrationStatus.Set(1)
		logger.Info("Data migrations are disabled, skipping",
			"unifiedStorageType", p.cfg.UnifiedStorageType(),
			"target", p.cfg.Target,
		)
		return nil
	}

	logger.Info("Running migrations for unified storage")
	metrics.MUnifiedStorageMigrationStatus.Set(3)
	return RegisterMigrations(ctx, p.migrator, p.tableLocker, p.tableRenamer, p.cfg, p.sqlStore, p.client, p.registry)
}

// EnsureMigrationLogTable creates the unifiedstorage_migration_log table if it doesn't exist.
func EnsureMigrationLogTable(ctx context.Context, sqlStore db.DB, cfg *setting.Cfg) error {
	exists, err := sqlStore.GetEngine().IsTableExist(migrationLogTableName)
	if err != nil {
		return fmt.Errorf("failed to check migration log table existence: %w", err)
	}
	if exists {
		return nil
	}

	mg := sqlstoremigrator.NewScopedMigrator(sqlStore.GetEngine(), cfg, "unifiedstorage")
	mg.AddCreateMigration()
	sec := cfg.Raw.Section("database")
	return mg.RunMigrations(ctx,
		sec.Key("migration_locking").MustBool(true),
		sec.Key("locking_attempt_timeout_sec").MustInt())
}

func RegisterMigrations(
	ctx context.Context,
	migrator UnifiedMigrator,
	tableLocker MigrationTableLocker,
	tableRenamer MigrationTableRenamer,
	cfg *setting.Cfg,
	sqlStore db.DB,
	client resource.ResourceClient,
	registry *MigrationRegistry,
) error {
	ctx, span := tracer.Start(ctx, "storage.unified.RegisterMigrations")
	defer span.End()
	mg := sqlstoremigrator.NewScopedMigrator(sqlStore.GetEngine(), cfg, "unifiedstorage")
	mg.AddCreateMigration()

	if err := prometheus.Register(mg); err != nil {
		logger.Warn("Failed to register migrator metrics", "error", err)
	}

	if err := validateRegisteredResources(registry); err != nil {
		return err
	}

	if err := registerMigrations(cfg, mg, migrator, tableLocker, tableRenamer, client, registry); err != nil {
		return err
	}

	// Run all registered migrations (blocking)
	sec := cfg.Raw.Section("database")

	// Chunked writes need the advisory lock for HA read-isolation: without it,
	// readers on other instances may see partially migrated data.
	if cfg.MigrationChunkedWrites && !sec.Key("migration_locking").MustBool(true) {
		logger.Warn("migration_chunked_writes needs migration_locking for HA read-isolation; " +
			"readers may see partially migrated data")
	}

	db := mg.DBEngine.DB().DB
	maxOpenConns := db.Stats().MaxOpenConnections
	maxConcurrentRenameConns := 0
	if mg.Dialect.DriverName() == sqlstoremigrator.MySQL {
		for _, m := range registry.All() {
			maxConcurrentRenameConns = max(maxConcurrentRenameConns, len(m.RenameTables))
		}
	}
	// Migrations require multiple concurrent connections:
	// 1 for advisory lock session, 1 for migration session,
	// 1 for READ lock (MySQL), 1 for legacy table reads (migrators),
	// and 1 per concurrent RENAME connection on MySQL
	neededConns := 4 + maxConcurrentRenameConns
	if maxOpenConns < neededConns {
		db.SetMaxOpenConns(neededConns)
		defer db.SetMaxOpenConns(maxOpenConns)
	}
	err := mg.RunMigrations(ctx,
		sec.Key("migration_locking").MustBool(true),
		sec.Key("locking_attempt_timeout_sec").MustInt())
	if err != nil {
		return fmt.Errorf("unified storage data migration failed: %w", err)
	}

	logger.Info("Unified storage migrations completed successfully")
	return nil
}
